mapper.select:
SELECT a.owner_id AS c0, a.balance_cents AS c1, COALESCE( (SELECT MAX(l.created_at) FROM wallet_ledger l WHERE l.domain = a.domain AND l.owner_id = a.owner_id AND l.balance_after >= 0), (SELECT MIN(l2.created_at) FROM wallet_ledger l2 WHERE l2.domain = a.domain AND l2.owner_id = a.owner_id) ) AS c2 FROM wallet_account a WHERE a.domain = #{domain} AND a.balance_cents < 0
AND a.owner_id = #{ownerId}
ORDER BY a.balance_cents ASC

mapper.update:
UPDATE wallet_account
   SET balance_cents = #{balanceCents},
       frozen_cents  = #{frozenCents},
       updated_at    = #{updatedAt}
 WHERE domain = #{domain} AND owner_id = #{ownerId}
